const metaYesterday = $('Fetch Meta Yesterday').item.json;
const meta7d = $('Fetch Meta 7 Days').item.json;
const historical = $('Fetch Historical Data').all() || [];

const processCampaigns = (data) => (data.data || []).map(c => {
  const conversions = (c.actions || []).find(a => a.action_type === 'offsite_conversion');
  return {
    id: c.campaign_id,
    name: c.campaign_name,
    spend: parseFloat(c.spend || 0),
    impressions: parseInt(c.impressions || 0),
    clicks: parseInt(c.clicks || 0),
    conversions: parseInt(conversions?.value || 0),
    ctr: parseFloat(c.ctr || 0),
    cpc: parseFloat(c.cpc || 0),
    reach: parseInt(c.reach || 0)
  };
});

return {
  json: {
    yesterday: processCampaigns(metaYesterday),
    last_7_days: processCampaigns(meta7d),
    historical_count: historical.length,
    report_date: new Date().toISOString().split('T')[0],
    target_cpa: parseFloat($env.TARGET_CPA || 20),
    daily_budget: parseFloat($env.DAILY_AD_BUDGET || 100)
  }
};

